import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_xor_instance(n):
        return [random.randint(0, 1) for _ in range(n)]

    def communication_complexity(xor_instance):
        n = len(xor_instance)
        return n

    def minimal_order_of_entangled_state(xor_instance):
        n = len(xor_instance)
        if n == 1:
            return 1
        elif n == 2:
            return 2
        else:
            return math.ceil(math.log2(n))

    instances_tested = 0
    total_rho = 0.0
    total_Q = 0.0

    for _ in range(100):
        xor_instance = generate_xor_instance(random.randint(5, 40))
        rho = minimal_order_of_entangled_state(xor_instance)
        Q = communication_complexity(xor_instance)

        if rho == 1 and Q != communication_complexity(generate_xor_instance(2)):
            return {
                "metric_name": "rho_vs_Q",
                "metric_value": None,
                "instances_tested": instances_tested,
                "conjecture_holds": False,
                "counterexample": f"Instance with rho=1 and non-Θ(f(n)) Q"
            }

        total_rho += rho
        total_Q += Q
        instances_tested += 1

    mean_rho = total_rho / instances_tested
    mean_Q = total_Q / instances_tested

    correlation_coefficient = (instances_tested * sum(rho * Q for rho, Q in zip([minimal_order_of_entangled_state(generate_xor_instance(random.randint(5, 40))) for _ in range(instances_tested)], [communication_complexity(generate_xor_instance(random.randint(5, 40))) for _ in range(instances_tested)])) - instances_tested * mean_rho * mean_Q) / (instances_tested * sum((rho - mean_rho) ** 2 for rho in [minimal_order_of_entangled_state(generate_xor_instance(random.randint(5, 40))) for _ in range(instances_tested)]) * sum((Q - mean_Q) ** 2 for Q in [communication_complexity(generate_xor_instance(random.randint(5, 40))) for _ in range(instances_tested)])) ** 0.5)

    return {
        "metric_name": "rho_vs_Q",
        "metric_value": correlation_coefficient,
        "instances_tested": instances_tested,
        "conjecture_holds": correlation_coefficient > 0.7,
        "counterexample": ""
    }

if __name__ == "__main__":
    seeds = [int(x) for x in sys.argv[1:]] or list(range(2, 30)) + [random.randint(100, 999) for _ in range(25)]

